[
    {
        "title": "审题",
        "description": "侧面展开图的长等于长方体底面的周长，宽等于长方体的高。因此，底面周长为24厘米，高为6厘米。",
        "bubbleText": "展开后，四个侧面连成一条带。它的长就是底面绕一圈的长度，宽就是纸盒的高。",
        "bubblePos": {
            "x": 410.0,
            "y": 100.0
        },
        "arrowTarget": {
            "x": 240.0,
            "y": 345.0
        }
    },
    {
        "title": "求底边",
        "description": "设底面正方形的边长为 $a$ 厘米，则 $4a=24$，所以 $a=6$（厘米）。",
        "bubbleText": "正方形有4条一样长的边，所以用 $24÷4$，得到每条边是6厘米。",
        "bubblePos": {
            "x": 450.0,
            "y": 100.0
        },
        "arrowTarget": {
            "x": 530.0,
            "y": 305.0
        },
        "motions": {
            "sideBand": "translate(50,0)"
        }
    },
    {
        "title": "算底面积",
        "description": "底面是正方形，底面积为 $a^2=6^2=36$（平方厘米）。",
        "bubbleText": "边长知道了，就能算正方形底面：$6×6=36$平方厘米。",
        "bubblePos": {
            "x": 440.0,
            "y": 100.0
        },
        "arrowTarget": {
            "x": 390.0,
            "y": 405.0
        }
    },
    {
        "title": "计算体积",
        "description": "长方体体积等于底面积乘高，所以 $V=36×6=216$（立方厘米）。检验：底面周长 $4×6=24$ 厘米，与展开图的长相符。答：这个长方体纸盒的体积是216立方厘米。",
        "bubbleText": "最后用底面积乘高：$36×6=216$。再检查周长，$4×6=24$，正好符合题意。",
        "bubblePos": {
            "x": 440.0,
            "y": 100.0
        },
        "arrowTarget": {
            "x": 240.0,
            "y": 345.0
        }
    }
]
